;; cleat-127: unhinted arrays used inside loops are speculated by element type; output must be identical with CLEAT_NO_OPT=arrayspec
(defn show [& xs] (println (apply pr-str xs)))
(defn r [e] (try (e) (catch Exception ex (str (.GetType ex) ": " (.Message ex)))))
(defn sum-u [a] (let [n (alength a)] (loop [i 0 s 0] (if (< i n) (recur (inc i) (+ s (aget a i))) s))))
(defn fill-u [a v] (let [n (alength a)] (loop [i 0] (when (< i n) (aset a i v) (recur (inc i))))) a)
(defn fill-i [a] (let [n (alength a)] (loop [i 0] (when (< i n) (aset a i (* 3 i)) (recur (inc i))))) a)
(defn fill-d [a] (let [n (alength a)] (loop [i 0] (when (< i n) (aset a i (* 0.5 i)) (recur (inc i))))) a)
(defn firsts [a] (loop [i 0 acc []] (if (< i (alength a)) (recur (inc i) (conj acc (aget a i))) acc)))
(defn walk-to [a k] (loop [i 0] (if (< i k) (do (aget a i) (recur (inc i))) :done)))
(show (sum-u (long-array [1 2 3])) (sum-u (double-array [0.5 1.5])) (sum-u (int-array [4 5])) (sum-u (short-array [1 2]))
      (sum-u (object-array [1 2.5 3N])) (sum-u (object-array [1 2])) (sum-u (byte-array [(byte 200)])) (sum-u (float-array [(float 1.5)])))
(show (map type [(sum-u (long-array [1])) (sum-u (double-array [1.0])) (sum-u (object-array [1N]))]))
(show (vec (fill-u (long-array 3) 7)) (vec (fill-u (double-array 2) 2)) (vec (fill-u (object-array 2) :k)) (r #(vec (fill-u (long-array 2) 1.5))) (r #(vec (fill-u (long-array 2) "x"))))
(show (vec (fill-i (long-array 4))) (vec (fill-i (object-array 3))) (vec (fill-i (double-array 2))) (r #(vec (fill-i (int-array 3)))) (vec (fill-d (double-array 3))) (vec (fill-d (object-array 2))) (r #(vec (fill-d (long-array 2)))))
(show (firsts (long-array [9 8])) (firsts (object-array [:a nil "s"])) (firsts (double-array [1.25])) (firsts (char-array [\a \b])) (firsts (boolean-array [true false])))
(show (r #(sum-u nil)) (r #(sum-u [1 2])) (r #(walk-to (long-array 2) 5)) (r #(walk-to (object-array 1) 3)) (walk-to (long-array 3) 3))
(show (r #(sum-u (long-array [Int64/MaxValue 1]))) (sum-u (long-array 0)) (sum-u (object-array 0)))
(defn mk [] (fn [a] (loop [i 0 s 0.0] (if (< i (alength a)) (recur (inc i) (+ s (aget a i))) s))))
(show ((mk) (double-array [1.5 2.5])) ((mk) (long-array [1 2])) ((mk) (object-array [0.25])))
(defn nested [a b] (loop [i 0 s 0] (if (< i (alength a)) (recur (inc i) (+ s (loop [j 0 t 0] (if (< j (alength b)) (recur (inc j) (+ t (* (aget a i) (aget b j)))) t)))) s)))
(show (nested (long-array [1 2]) (long-array [3 4])) (nested (double-array [0.5]) (long-array [2 4])) (nested (object-array [1]) (double-array [1.5])))
